:root {
  --bg: #020b08;
  --panel: rgba(7, 32, 25, 0.9);
  --panel-border: rgba(100, 255, 184, 0.7);
  --green: #69ffb2;
  --green-strong: #a3ff7d;
  --green-soft: #1c5d47;
  --danger: #ff5d5d;
  --amber: #ffc857;
  --shadow: rgba(0, 0, 0, 0.45);
}

* {
  box-sizing: border-box;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at top, rgba(11, 30, 24, 1) 0%, rgba(1, 7, 7, 1) 58%);
  font-family: Arial, Helvetica, sans-serif;
  color: var(--green);
}

body {
  position: relative;
  display: flex;
  align-items: stretch;
  justify-content: center;
}

#gameCanvas {
  width: 100vw;
  height: 100vh;
  display: block;
  background: linear-gradient(180deg, rgba(3, 8, 7, 0.96), rgba(1, 7, 7, 1));
  box-shadow: inset 0 0 25px rgba(101, 255, 162, 0.12);
}

.hud {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 14px 18px 0;
  pointer-events: none;
}

.brand-wrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  border: 1px solid rgba(105, 255, 178, 0.8);
  background: rgba(1, 17, 12, 0.76);
  box-shadow: 0 0 14px rgba(105, 255, 178, 0.15);
  letter-spacing: 0.2em;
}

.brand {
  font-size: clamp(10px, 1.1vw, 18px);
  font-weight: 700;
}

.stats {
  display: flex;
  gap: 14px;
}

.stat {
  min-width: 88px;
  padding: 8px 12px;
  text-align: center;
  background: rgba(1, 17, 12, 0.8);
  border: 1px solid rgba(105, 255, 178, 0.8);
  box-shadow: 0 0 14px rgba(105, 255, 178, 0.12);
}

.label {
  display: block;
  font-size: 10px;
  letter-spacing: 0.2em;
  opacity: 0.8;
}

.stat span:last-child {
  display: block;
  margin-top: 4px;
  font-size: clamp(18px, 2vw, 32px);
  font-weight: 700;
}

.overlay {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(0, 0, 0, 0.38);
  z-index: 20;
}

.overlay.hidden {
  display: none;
}

.panel {
  width: min(520px, 90vw);
  padding: 28px 26px 24px;
  background: rgba(4, 20, 18, 0.92);
  border: 1px solid var(--panel-border);
  box-shadow: 0 0 18px rgba(9, 255, 171, 0.2), inset 0 0 18px rgba(9, 255, 171, 0.08);
  text-align: center;
}

.eyebrow {
  margin: 0 0 12px;
  font-size: 11px;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  opacity: 0.8;
}

h1, h2 {
  margin: 0 0 18px;
  font-size: clamp(30px, 5vw, 52px);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.panel p, .panel li {
  font-size: clamp(14px, 1.6vw, 18px);
  line-height: 1.6;
  color: rgba(198, 255, 223, 0.95);
}

.panel ul {
  list-style: none;
  padding: 0;
  margin: 18px 0 22px;
  display: grid;
  grid-template-columns: repeat(2, minmax(130px, 1fr));
  gap: 8px 16px;
}

button {
  appearance: none;
  border: 1px solid var(--panel-border);
  background: linear-gradient(180deg, rgba(8, 38, 27, 1), rgba(3, 16, 11, 1));
  color: var(--green);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 14px 22px;
  font-size: 12px;
  cursor: pointer;
  box-shadow: 0 0 16px rgba(105, 255, 178, 0.2);
}

button:active {
  transform: translateY(1px);
}

@media (max-width: 640px) {
  .hud {
    padding: 12px 12px 0;
  }

  .brand-wrap {
    letter-spacing: 0.12em;
    padding: 6px 10px;
  }

  .stats {
    gap: 8px;
  }

  .stat {
    min-width: 70px;
    padding: 7px 8px;
  }

  .panel ul {
    grid-template-columns: 1fr;
  }
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const waveEl = document.getElementById('wave');
const citiesEl = document.getElementById('cities');
const startOverlay = document.getElementById('startOverlay');
const gameOverOverlay = document.getElementById('gameOverOverlay');
const finalScoreEl = document.getElementById('finalScore');

const cityConfigs = [
  { name: 'Las Vegas', x: 0.26, y: 0.84, radius: 18 },
  { name: 'New York', x: 0.18, y: 0.68, radius: 16 },
  { name: 'Los Angeles', x: 0.38, y: 0.76, radius: 17 },
  { name: 'São Paulo', x: 0.72, y: 0.8, radius: 17 },
  { name: 'Curitiba', x: 0.8, y: 0.7, radius: 15 },
  { name: 'Rio de Janeiro', x: 0.68, y: 0.72, radius: 16 }
];

const state = {
  running: false,
  score: 0,
  wave: 1,
  cityCount: 3,
  threatLevel: 0,
  lastTime: 0,
  enemySpawnTimer: 0,
  skyline: [],
  enemies: [],
  missiles: [],
  explosions: [],
  cities: [],
  pointer: { x: 0, y: 0, active: false },
  flashTimer: 0,
  message: '',
  messageTimer: 0,
  musicPulse: 0,
};

function resizeCanvas() {
  const ratio = window.devicePixelRatio || 1;
  canvas.width = Math.floor(window.innerWidth * ratio);
  canvas.height = Math.floor(window.innerHeight * ratio);
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
  state.width = window.innerWidth;
  state.height = window.innerHeight;
  if (!state.cities.length) {
    createCities();
  }
}

function createCities() {
  const count = Math.min(state.cityCount, cityConfigs.length);
  state.cities = cityConfigs.slice(0, count).map((city, index) => ({
    ...city,
    active: true,
    x: city.x * state.width,
    y: city.y * state.height,
    pulse: index * 0.7,
  }));
}

function resetGame() {
  state.running = true;
  state.score = 0;
  state.wave = 1;
  state.cityCount = 3;
  state.threatLevel = 0;
  state.enemies = [];
  state.missiles = [];
  state.explosions = [];
  state.enemySpawnTimer = 0;
  state.flashTimer = 0;
  state.message = 'DEFENSE GRID ONLINE';
  state.messageTimer = 2.2;
  createCities();
  updateHud();
  hideGameOver();
}

function updateHud() {
  scoreEl.textContent = String(state.score);
  waveEl.textContent = String(state.wave);
  citiesEl.textContent = String(state.cityCount);
}

function hideGameOver() {
  gameOverOverlay.classList.add('hidden');
}

function showGameOver() {
  finalScoreEl.textContent = String(state.score);
  gameOverOverlay.classList.remove('hidden');
}

function spawnEnemy() {
  const enemyCount = 1 + Math.min(2, Math.floor(state.wave / 2));
  const base = cityConfigs[Math.floor(Math.random() * state.cities.length)] || cityConfigs[0];
  for (let i = 0; i < enemyCount; i++) {
    const side = Math.random() < 0.5 ? -40 : state.width + 40;
    const x = side;
    const y = 60 + Math.random() * (state.height * 0.5);
    const targetCity = state.cities[Math.floor(Math.random() * state.cities.length)] || { x: state.width * 0.5, y: state.height * 0.75 };
    const angle = Math.atan2(targetCity.y - y, targetCity.x - x);
    state.enemies.push({
      x,
      y,
      targetX: targetCity.x,
      targetY: targetCity.y,
      vx: Math.cos(angle) * (1.2 + state.wave * 0.18),
      vy: Math.sin(angle) * (1.2 + state.wave * 0.18),
      radius: 9 + Math.random() * 4,
      type: Math.random() < 0.7 ? 'bomber' : 'missile',
      hit: false,
      trail: [],
      hue: Math.random() < 0.5 ? 115 : 80,
    });
  }
}

function shootAt(x, y) {
  if (!state.running) return;
  const originX = state.width * 0.5;
  const originY = state.height - 42;
  const angle = Math.atan2(y - originY, x - originX);
  const speed = 7.5;
  const dx = Math.cos(angle) * speed;
  const dy = Math.sin(angle) * speed;
  state.missiles.push({
    x: originX,
    y: originY,
    vx: dx,
    vy: dy,
    radius: 5,
    life: 0,
  });
}

function getClosestEnemy(x, y) {
  let closest = null;
  let bestDistance = Infinity;
  for (const enemy of state.enemies) {
    const distance = Math.hypot(enemy.x - x, enemy.y - y);
    if (distance < bestDistance) {
      bestDistance = distance;
      closest = enemy;
    }
  }
  return closest;
}

function update(dt) {
  if (!state.running) return;

  state.threatLevel += dt * 0.08;
  state.enemySpawnTimer -= dt;
  if (state.enemySpawnTimer <= 0) {
    spawnEnemy();
    state.enemySpawnTimer = Math.max(0.7, 2.2 - state.wave * 0.12);
  }

  if (state.score > 0 && state.score % 120 === 0 && state.wave < 12) {
    state.wave = 1 + Math.floor(state.score / 120);
  }

  for (const city of state.cities) {
    city.pulse += dt * 2;
  }

  for (const missile of state.missiles) {
    missile.x += missile.vx * 60 * dt;
    missile.y += missile.vy * 60 * dt;
    missile.life += dt;

    let hitEnemy = null;
    for (const enemy of state.enemies) {
      if (!enemy.hit && Math.hypot(enemy.x - missile.x, enemy.y - missile.y) < enemy.radius + missile.radius + 4) {
        hitEnemy = enemy;
        break;
      }
    }

    if (hitEnemy) {
      hitEnemy.hit = true;
      state.explosions.push({
        x: hitEnemy.x,
        y: hitEnemy.y,
        radius: 12,
        maxRadius: 36,
        alpha: 1,
        life: 0,
      });
      state.score += 10;
      state.missiles.splice(state.missiles.indexOf(missile), 1);
      state.enemies = state.enemies.filter((enemy) => enemy !== hitEnemy);
      updateHud();
      continue;
    }

    if (missile.life > 2.5 || missile.x < -20 || missile.y < -20 || missile.x > state.width + 20 || missile.y > state.height + 20) {
      state.missiles.splice(state.missiles.indexOf(missile), 1);
    }
  }

  for (const enemy of state.enemies) {
    enemy.x += enemy.vx * 60 * dt;
    enemy.y += enemy.vy * 60 * dt;
    enemy.trail.push({ x: enemy.x, y: enemy.y });
    if (enemy.trail.length > 8) enemy.trail.shift();

    if (Math.hypot(enemy.x - enemy.targetX, enemy.y - enemy.targetY) < 18) {
      const city = state.cities.find((c) => Math.hypot(c.x - enemy.targetX, c.y - enemy.targetY) < 90);
      if (city) {
        city.active = false;
        state.cityCount = state.cities.filter((c) => c.active).length;
        state.score = Math.max(0, state.score - 30);
        state.explosions.push({
          x: city.x,
          y: city.y,
          radius: 18,
          maxRadius: 70,
          alpha: 1,
          life: 0,
        });
      }
      state.enemies = state.enemies.filter((e) => e !== enemy);
      if (state.cityCount <= 0) {
        state.running = false;
        showGameOver();
      }
      updateHud();
      continue;
    }
  }

  for (const explosion of state.explosions) {
    explosion.life += dt;
    explosion.radius = 12 + explosion.life * 60;
    explosion.alpha = Math.max(0, 1 - explosion.life / 0.9);
    if (explosion.life > 0.9) {
      state.explosions.splice(state.explosions.indexOf(explosion), 1);
    }
  }

  if (state.messageTimer > 0) {
    state.messageTimer -= dt;
  }
}

function drawBackground() {
  ctx.fillStyle = '#040b07';
  ctx.fillRect(0, 0, state.width, state.height);

  for (let y = 0; y < state.height; y += 18) {
    ctx.strokeStyle = 'rgba(105,255,178,0.08)';
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(state.width, y);
    ctx.stroke();
  }

  for (let x = 0; x < state.width; x += 26) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, state.height);
    ctx.strokeStyle = 'rgba(105,255,178,0.03)';
    ctx.stroke();
  }

  const groundY = state.height - 26;
  ctx.fillStyle = 'rgba(16, 45, 35, 0.95)';
  ctx.fillRect(0, groundY, state.width, state.height - groundY);

  ctx.strokeStyle = 'rgba(105,255,178,0.25)';
  ctx.lineWidth = 1;
  for (let i = 0; i < state.width; i += 28) {
    ctx.beginPath();
    ctx.moveTo(i, groundY);
    ctx.lineTo(i + 10, state.height);
    ctx.stroke();
  }

  ctx.fillStyle = 'rgba(105,255,178,0.12)';
  for (let i = 0; i < 40; i++) {
    const x = (i * 67 + (state.threatLevel * 17) % 100) % (state.width + 30);
    const y = 40 + (i * 37) % (state.height * 0.38);
    ctx.fillRect(x, y, 2, 2);
  }
}

function drawCities() {
  for (const city of state.cities) {
    if (!city.active) continue;
    const pulse = 1 + Math.sin(city.pulse) * 0.15;
    ctx.beginPath();
    ctx.fillStyle = 'rgba(105,255,178,0.18)';
    ctx.arc(city.x, city.y, city.radius * 1.6 * pulse, 0, Math.PI * 2);
    ctx.fill();

    ctx.beginPath();
    ctx.fillStyle = '#7dffba';
    ctx.arc(city.x, city.y, city.radius * pulse, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = 'rgba(3, 12, 10, 0.9)';
    ctx.fillRect(city.x - 18, city.y + 18, 36, 18);
    ctx.fillStyle = '#bfffe0';
    ctx.font = '12px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(city.name.split(' ')[0], city.x, city.y + 31);
  }
}

function drawDefenseBase() {
  const x = state.width * 0.5;
  const y = state.height - 25;
  ctx.strokeStyle = '#7eeab0';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x - 60, y);
  ctx.lineTo(x + 60, y);
  ctx.lineTo(x + 20, y - 34);
  ctx.lineTo(x - 20, y - 34);
  ctx.closePath();
  ctx.stroke();

  ctx.beginPath();
  ctx.fillStyle = '#a3ff7d';
  ctx.arc(x, y - 32, 8, 0, Math.PI * 2);
  ctx.fill();
}

function drawMissiles() {
  for (const missile of state.missiles) {
    ctx.beginPath();
    ctx.strokeStyle = '#9dffb3';
    ctx.lineWidth = 2;
    ctx.moveTo(missile.x, missile.y);
    ctx.lineTo(missile.x - missile.vx * 4, missile.y - missile.vy * 4);
    ctx.stroke();

    ctx.beginPath();
    ctx.fillStyle = '#b6ffd5';
    ctx.arc(missile.x, missile.y, missile.radius, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawEnemies() {
  for (const enemy of state.enemies) {
    ctx.beginPath();
    ctx.fillStyle = 'rgba(255, 120, 120, 0.7)';
    for (let i = 0; i < enemy.trail.length; i++) {
      const pos = enemy.trail[i];
      const a = i / enemy.trail.length;
      ctx.fillStyle = `rgba(255, 120, 120, ${0.2 + a * 0.7})`;
      ctx.fillRect(pos.x - 2, pos.y - 2, 4, 4);
    }

    ctx.beginPath();
    ctx.fillStyle = enemy.type === 'bomber' ? '#ff6b6b' : '#ff8a5b';
    ctx.moveTo(enemy.x, enemy.y - enemy.radius);
    ctx.lineTo(enemy.x + enemy.radius * 1.2, enemy.y);
    ctx.lineTo(enemy.x, enemy.y + enemy.radius);
    ctx.lineTo(enemy.x - enemy.radius * 1.2, enemy.y);
    ctx.closePath();
    ctx.fill();
  }
}

function drawExplosions() {
  for (const explosion of state.explosions) {
    ctx.beginPath();
    ctx.strokeStyle = `rgba(255, 210, 113, ${explosion.alpha})`;
    ctx.lineWidth = 3;
    ctx.arc(explosion.x, explosion.y, explosion.radius, 0, Math.PI * 2);
    ctx.stroke();

    ctx.beginPath();
    ctx.fillStyle = `rgba(255, 120, 120, ${explosion.alpha * 0.5})`;
    ctx.arc(explosion.x, explosion.y, explosion.radius * 0.45, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawMessage() {
  if (state.messageTimer <= 0) return;
  ctx.fillStyle = 'rgba(0, 0, 0, 0.25)';
  ctx.fillRect(state.width * 0.5 - 140, 34, 280, 40);
  ctx.fillStyle = '#d7ffe7';
  ctx.font = 'bold 18px Arial';
  ctx.textAlign = 'center';
  ctx.fillText(state.message, state.width * 0.5, 60);
}

function render() {
  drawBackground();
  drawCities();
  drawDefenseBase();
  drawMissiles();
  drawEnemies();
  drawExplosions();
  drawMessage();
}

function loop(timestamp) {
  const dt = Math.min((timestamp - state.lastTime)/1000 || 0.016, 0.033);
  state.lastTime = timestamp;
  update(dt);
  render();
  requestAnimationFrame(loop);
}

canvas.addEventListener('pointerdown', (event) => {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;
  state.pointer = { x, y, active: true };
  shootAt(x, y);
});

window.addEventListener('resize', resizeCanvas);

document.getElementById('startButton').addEventListener('click', () => {
  startOverlay.classList.add('hidden');
  resetGame();
});

document.getElementById('restartButton').addEventListener('click', () => {
  resetGame();
});

resizeCanvas();
render();
requestAnimationFrame(loop);

